import OurProductHeader from '../../FieldManagementDetail/OurProductHeader';
import Footer from '../../Footer/Footer';
import SEOComponent from '../../common/SEOComponent';
import RemoteMonitoring from './RemoteMonitoring';
import TimeSeries from './TimeSeries';
import TransformerMeasure from './TransformerMeasure';
import TransformerSafety from './TransformerSafety';

const SmartTransformerPage = () => {
  ScrollUp();
  return (
    <div className='rupantor-inventory overflow-hidden'>
      <SEOComponent key='suffix, suffixit, Rupantar, Rupantar HCM, Rupantar HR, Rupantar Payroll, HCM, HR, Payroll, HCM Rupantar, HR Rupantar, Payroll Rupantar, Provident Fund, Suffix Provident Fund, Suffix PF, Rupantar ERP, REP, ERP Rupantar, Suffix ERP, Suffix E-commerce, E-commerce, Ecommerce, Ecommerce Suffix, Suffix FFMS, FFMS, Field Force, Field Force Management System, Suffix Interconnect Billing, Interconnect Billing, Billing, Suffix Hotel, Suffix Hotel Booking System, Hotel Booking System, Booking System, Domain, Hosting, Domain and Hosting, Web And Ecommerce, Storage, Backup Services, Storage and Backup Services, Cloud, Cloud Hosting, Suffix Bulk SMS, SMS, Bulk SMS, ERP Consulting, Applications, Custom Applications, Mobile, Mobile Applications, Mobile apps, inventory, Inventory Management, Sales Orders, Invoicing, Procurement, Accounting and financial Management, software company in Bangladesh,software development in Bangladesh,Mobile App development company in Bangladesh,Android App Development,iOS App Development,software development company in Bangladesh,website developer company in Bangladesh,create software program,best hosting company in Bangladesh,web hosting company in Bangladesh,domain hosting Bangladesh,seo service provider company in Bangladesh,best website design company in Bangladesh,erp software company in Bangladesh,pos software company in Bangladesh,pos software company in bd,accounting software company in Bangladesh,leading software company in Bangladesh,software company in bangladesh list,top 10 software development company in Bangladesh,Graphics Design,Inventory,Library Software,IT,bd,bangladesh, webmeeting, suffix webmeeting, pos, smart pos, smart pos and billing, pos solution, smart pos and billing system, pos system' />
      <OurProductHeader
        title='Smart Transformer Monitoring System'
        hyperRef='rupantor-inventory#rupantor-inventory-intro'
        img={img}
        imgWidth='100%'
      />
      <div className='row d-flex justify-content-around align-items-center px-5'>
        <h1
          className='text-center'
          style={{
            fontSize: '28px',
            fontWeight: '700',
            color: ' #80bfff',
          }}
        >
          SYSTEM FEATURES
        </h1>
        <img
          src={inventoryFeatureImg}
          alt='interconnect billing'
          style={{ width: '80%', height: 'auto', objectFit: 'contain' }}
        />
      </div>
      <RemoteMonitoring />

      <TransformerMeasure />
      <TimeSeries />
      <TransformerSafety />

      <FieldForceDemo />
      <Footer />
    </div>
  );
};

export default SmartTransformerPage;
